//! End-to-end coverage for the owned native product command. The command's
//! source input is lowered and code-generated by LAMINARIA; this test only
//! supplies the Darwin runtime/link facts which the command deliberately
//! requires explicitly.

#![cfg(all(target_arch = "aarch64", target_os = "macos"))]

use std::path::{Path, PathBuf};
use std::process::Command;

fn laminaria_bin() -> &'static Path {
    Path::new(env!("CARGO_BIN_EXE_laminaria"))
}

fn temp_dir(name: &str) -> PathBuf {
    let root = std::env::temp_dir().join(format!(
        "laminaria-owned-native-build-cli-{name}-{}",
        std::process::id()
    ));
    let _ = std::fs::remove_dir_all(&root);
    std::fs::create_dir_all(&root).unwrap();
    root
}

fn macos_sdk_root() -> PathBuf {
    let output = Command::new("xcrun")
        .arg("--show-sdk-path")
        .output()
        .expect("xcrun must be available on the declared Darwin target");
    assert!(
        output.status.success(),
        "xcrun --show-sdk-path failed: {}",
        String::from_utf8_lossy(&output.stderr)
    );
    PathBuf::from(String::from_utf8(output.stdout).unwrap().trim())
}

fn owned_native_command(source: &Path, output_dir: &Path) -> Command {
    owned_native_command_for_entry_and_version(source, output_dir, "main", "11.0")
}

fn owned_native_command_for_entry(source: &Path, output_dir: &Path, entry: &str) -> Command {
    owned_native_command_for_entry_and_version(source, output_dir, entry, "11.0")
}

fn owned_native_command_for_entry_and_version(
    source: &Path,
    output_dir: &Path,
    entry: &str,
    minimum_macos_version: &str,
) -> Command {
    let mut command = Command::new(laminaria_bin());
    command
        .args(["owned-native-build", "--source"])
        .arg(source)
        .args(["--entry", entry])
        .args(["--output-dir"])
        .arg(output_dir)
        .args(["--linker", "/usr/bin/ld", "--sdk-root"])
        .arg(macos_sdk_root())
        .args(["--minimum-macos-version", minimum_macos_version, "--json"]);
    command
}

fn json_stdout(output: &std::process::Output) -> serde_json::Value {
    serde_json::from_slice(&output.stdout).unwrap_or_else(|error| {
        panic!(
            "expected JSON stdout ({error}); stdout: {}; stderr: {}",
            String::from_utf8_lossy(&output.stdout),
            String::from_utf8_lossy(&output.stderr)
        )
    })
}

#[test]
fn owned_native_build_lowers_links_and_launches_supported_main() {
    let root = temp_dir("success");
    let source = root.join("main.rs");
    let output_dir = root.join("out");
    std::fs::write(
        &source,
        "use std::process;\nfn status() -> i32 { 2i32.wrapping_add(5) }\nfn main() { process::exit(status()); }\n",
    )
    .unwrap();

    let output = owned_native_command(&source, &output_dir).output().unwrap();
    assert!(
        output.status.success(),
        "owned-native-build failed: stdout={} stderr={}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    let json = json_stdout(&output);
    assert_eq!(json["ok"], true);
    assert_eq!(json["result"]["entry"], "main");
    assert_eq!(json["result"]["toolchain"]["linker"], "/usr/bin/ld");
    assert_eq!(json["result"]["toolchain"]["minimum_macos_version"], "11.0");

    let object = PathBuf::from(json["result"]["object_path"].as_str().unwrap());
    let executable = PathBuf::from(json["result"]["executable_path"].as_str().unwrap());
    assert!(object.is_file(), "missing object: {}", object.display());
    assert!(
        executable.is_file(),
        "missing executable: {}",
        executable.display()
    );
    assert_eq!(Command::new(executable).status().unwrap().code(), Some(7));

    let _ = std::fs::remove_dir_all(root);
}

