#[test]
fn owned_native_build_records_its_declared_platform_version_in_the_object() {
    let root = temp_dir("platform-version");
    let source = root.join("main.rs");
    let output_dir = root.join("out");
    std::fs::write(&source, "fn main() { std::process::exit(7i32); }\n").unwrap();

    let output = owned_native_command_for_entry_and_version(&source, &output_dir, "main", "12.3.4")
        .output()
        .unwrap();
    assert!(
        output.status.success(),
        "owned-native-build failed: stdout={} stderr={}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    let json = json_stdout(&output);
    assert_eq!(
        json["result"]["toolchain"]["minimum_macos_version"],
        "12.3.4"
    );
    let object = std::fs::read(json["result"]["object_path"].as_str().unwrap()).unwrap();
    // `LC_BUILD_VERSION` begins after the 32-byte header and 152-byte
    // `LC_SEGMENT_64`; minos and sdk are both the declared target because
    // the explicit link action supplies that same value to `ld`.
    assert_eq!(
        u32::from_le_bytes(object[184..188].try_into().unwrap()),
        0x32
    );
    assert_eq!(
        u32::from_le_bytes(object[196..200].try_into().unwrap()),
        0x000c_0304
    );
    assert_eq!(
        u32::from_le_bytes(object[200..204].try_into().unwrap()),
        0x000c_0304
    );

    let _ = std::fs::remove_dir_all(root);
}

#[test]
fn owned_native_build_lowers_links_and_launches_source_conditional() {
    let root = temp_dir("conditional");
    let source = root.join("main.rs");
    let output_dir = root.join("out");
    std::fs::write(
        &source,
        r#"fn status() -> i32 {
            let zero = 3i32.wrapping_sub(3);
            if zero != 0 { 27 } else { 11 }
        }
        fn main() { std::process::exit(status()); }
        "#,
    )
    .unwrap();

    let output = owned_native_command(&source, &output_dir).output().unwrap();
    assert!(
        output.status.success(),
        "owned-native-build failed: stdout={} stderr={}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    let executable = PathBuf::from(
        json_stdout(&output)["result"]["executable_path"]
            .as_str()
            .unwrap(),
    );
    assert_eq!(Command::new(executable).status().unwrap().code(), Some(11));

    let _ = std::fs::remove_dir_all(root);
}

#[test]
fn owned_native_build_discovers_lowers_links_and_launches_transitive_calls() {
    let root = temp_dir("calls");
    let source = root.join("main.rs");
    let output_dir = root.join("out");
    std::fs::write(
        &source,
        r#"
        fn increment(x: i32) -> i32 { x.wrapping_add(1) }
        fn combine(x: i32) -> i32 { x.wrapping_add(increment(x)) }
        fn pack(left: i32, right: i32) -> i32 {
            left.wrapping_mul(10).wrapping_add(right)
        }
        fn main() { std::process::exit(pack(combine(3), increment(4))); }
        "#,
    )
    .unwrap();

    let output = owned_native_command(&source, &output_dir).output().unwrap();
    assert!(
        output.status.success(),
        "owned-native-build failed: stdout={} stderr={}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    let executable = PathBuf::from(
        json_stdout(&output)["result"]["executable_path"]
            .as_str()
            .unwrap(),
    );
    assert_eq!(Command::new(executable).status().unwrap().code(), Some(75));

    let _ = std::fs::remove_dir_all(root);
}

#[test]
fn owned_native_build_promotes_an_explicit_source_entry_to_darwin_main() {
    let root = temp_dir("explicit-entry");
    let source = root.join("main.rs");
    let output_dir = root.join("out");
    std::fs::write(
        &source,
        r#"
        fn increment(x: i32) -> i32 { x.wrapping_add(1) }
        fn laminaria_entry() -> i32 { increment(6) }
        fn main() { std::process::exit(laminaria_entry()); }
        "#,
    )
    .unwrap();

    let output = owned_native_command_for_entry(&source, &output_dir, "laminaria_entry")
        .output()
        .unwrap();
    assert!(
        output.status.success(),
        "owned-native-build failed: stdout={} stderr={}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    let json = json_stdout(&output);
    assert_eq!(json["result"]["entry"], "laminaria_entry");
    let executable = PathBuf::from(json["result"]["executable_path"].as_str().unwrap());
    assert_eq!(Command::new(executable).status().unwrap().code(), Some(7));

    let _ = std::fs::remove_dir_all(root);
}

#[test]
fn owned_native_build_reports_unsupported_source_before_linking() {
    let root = temp_dir("unsupported");
    let source = root.join("main.rs");
    let output_dir = root.join("out");
    std::fs::write(
        &source,
        "fn main() { println!(\"not in the owned subset\"); std::process::exit(0); }\n",
    )
    .unwrap();

    let output = owned_native_command(&source, &output_dir).output().unwrap();
    assert!(!output.status.success());
    let json = json_stdout(&output);
    assert_eq!(json["ok"], false);
    assert_eq!(json["error_kind"], "source_diagnostic");
    assert!(json["detail"].as_str().unwrap().contains("macro"));
    assert!(
        !output_dir.exists(),
        "rejected source must not leave a link/output directory"
    );

    let _ = std::fs::remove_dir_all(root);
}
